function tokenize(src) {
  const out = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (c === ' ' || c === '\t') { i++; continue; }      // 공백 건너뛰기
    if (/[0-9]/.test(c)) {                                 // 숫자
      let j = i; while (j < src.length && /[0-9]/.test(src[j])) j++;
      out.push({ type: 'num', value: src.slice(i, j), at: i }); i = j; continue;
    }
    if (/[a-zA-Z_]/.test(c)) {                             // 이름(식별자)
      let j = i; while (j < src.length && /[a-zA-Z0-9_]/.test(src[j])) j++;
      out.push({ type: 'id', value: src.slice(i, j), at: i }); i = j; continue;
    }
    const two = src.slice(i, i + 2);                       // 두 글자 연산자 먼저
    if (['>=', '<=', '==', '!='].includes(two)) { out.push({type:'op',value:two,at:i}); i+=2; continue; }
    if ('+-*/()<>='.includes(c)) { out.push({type:'op',value:c,at:i}); i++; continue; }
    throw new Error(`이상한 글자 '${c}' at ${i}`);          // 모르는 글자
  }
  out.push({ type: 'eof', at: i });                        // 끝 표시
  return out;
}
